def clock_dominates(clock_a: dict[str, int], clock_b: dict[str, int]) -> bool:
    """Return True when clock_a dominates clock_b.

    Missing components count as 0. A clock dominates another when it is
    greater than or equal on every component and strictly greater on at
    least one (i.e. A >= B and A != B).
    """
    keys = set(clock_a) | set(clock_b)
    strictly_greater = False
    for key in keys:
        a = clock_a.get(key, 0)
        b = clock_b.get(key, 0)
        if a < b:
            return False
        if a > b:
            strictly_greater = True
    return strictly_greater


def clock_direction(clock_a: dict[str, int], clock_b: dict[str, int]) -> str:
    """Classify two already-known-different clocks relative to each other.

    Returns ``"L"`` when ``clock_a`` dominates ``clock_b``, ``"R"`` when
    ``clock_b`` dominates ``clock_a``, and ``"C"`` when the clocks are
    concurrent — neither dominates the other. Equal clocks are never
    compared: the callers only ask for a direction when the clocks
    differ. Missing components count as 0, exactly as in
    :func:`clock_dominates`.
    """
    if clock_dominates(clock_a, clock_b):
        return "L"
    if clock_dominates(clock_b, clock_a):
        return "R"
    return "C"


def _validate_clock(clock: Any, replica_id: str) -> dict[str, int]:
    """Validate a vector clock for ``replica_id`` and return a clean copy."""
    if not isinstance(clock, dict) or not clock:
        raise ValueError("clock must be a non-empty object")
    if _MAX_CLOCK_COMPONENTS is not None and len(clock) > _MAX_CLOCK_COMPONENTS:
        raise ValueError("clock exceeds the configured maximum component count")
    for component, tick in clock.items():
        if not isinstance(component, str) or component == "":
            raise ValueError("clock components must be non-empty strings")
        if isinstance(tick, bool) or not isinstance(tick, int) or tick < 0:
            raise ValueError("clock values must be non-negative integers")
    if replica_id not in clock:
        raise ValueError("clock must contain the replica id")
    return dict(clock)


def parse_operation_payload(raw: bytes | str | dict[str, Any], replica_id: str) -> dict[str, Any]:
    """Parse and validate an operation payload for ``replica_id``.

    Accepts a JSON document (bytes or text) or an already-decoded mapping.
    Returns a normalized operation dict. Raises ValueError when the payload
    is malformed or fails validation.
    """
    if isinstance(raw, (bytes, bytearray)):
        try:
            raw = raw.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError("body must be UTF-8 JSON") from exc
    if isinstance(raw, str):
        try:
            payload: Any = json.loads(raw)
        except json.JSONDecodeError as exc:
            raise ValueError("body must be valid JSON") from exc
    else:
        payload = raw
    if not isinstance(payload, dict):
        raise ValueError("payload must be a JSON object")

    for field in ("operationId", "key", "value"):
        value = payload.get(field)
        if not isinstance(value, str) or value == "":
            raise ValueError(f"{field} must be a non-empty string")

    clock = _validate_clock(payload.get("clock"), replica_id)

    return {
        "operationId": payload["operationId"],
        "key": payload["key"],
        "value": payload["value"],
        "clock": dict(clock),
    }


def parse_conditional_operation_payload(
    raw: bytes | str | dict[str, Any], replica_id: str
) -> tuple[dict[str, Any], list[dict[str, str]]]:
    """Parse and validate a conditional-write payload for ``replica_id``.

    The body must be a JSON object with exactly ``operationId``, ``key``,
    ``value``, ``clock``, and ``expectedCandidates``. The first four follow
    the ordinary write constraints (see :func:`parse_operation_payload`);
    ``expectedCandidates`` is the candidate identity set the caller expects
    the key to currently hold — a list of distinct
    ``{"replicaId", "operationId"}`` identities, possibly empty (the key is
    expected to hold no candidates). Returns the normalized operation dict
    — the same shape an ordinary write commits, so identity replays match
    across both entry points — and the expected identities in request
    order. Raises ValueError on any violation.
    """
    if isinstance(raw, (bytes, bytearray)):
        try:
            raw = raw.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError("body must be UTF-8 JSON") from exc
    if isinstance(raw, str):
        try:
            payload: Any = json.loads(raw)
        except json.JSONDecodeError as exc:
            raise ValueError("body must be valid JSON") from exc
    else:
        payload = raw
    if not isinstance(payload, dict) or set(payload.keys()) != {
        "operationId",
        "key",
        "value",
        "clock",
        "expectedCandidates",
    }:
        raise ValueError(
            "payload must be an object with only operationId, key, value, "
            "clock, expectedCandidates"
        )

    operation = parse_operation_payload(payload, replica_id)

    expected_raw = payload["expectedCandidates"]
    if not isinstance(expected_raw, list):
        raise ValueError("expectedCandidates must be a list")
    expected: list[dict[str, str]] = []
    identities: set[tuple[str, str]] = set()
    for entry in expected_raw:
        if not isinstance(entry, dict) or set(entry.keys()) != {"replicaId", "operationId"}:
            raise ValueError(
                "each expected candidate must have only replicaId and operationId"
            )
        candidate_replica = entry["replicaId"]
        candidate_operation = entry["operationId"]
        if not isinstance(candidate_replica, str) or candidate_replica == "":
            raise ValueError("expected candidate replicaId must be a non-empty string")
        if not isinstance(candidate_operation, str) or candidate_operation == "":
            raise ValueError("expected candidate operationId must be a non-empty string")
        identity = (candidate_replica, candidate_operation)
        if identity in identities:
            raise ValueError(f"duplicate expected candidate {identity!r}")
        identities.add(identity)
        expected.append(
            {"replicaId": candidate_replica, "operationId": candidate_operation}
        )

    return operation, expected


